#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_property;
uniform float amzp_softness;
uniform float amzp_height;
uniform float amzp_cutMin;
uniform float amzp_cutMax;
uniform float amzp_lightDir;
uniform float amzp_lightHeight;
uniform float amzp_intensity;
layout(color) uniform half4 amzp_lightColor;
uniform float amzp_ambient;
uniform float amzp_diffuse;
uniform float amzp_specular;
uniform float amzp_roughness;
uniform float amzp_metal;
uniform float amzp_quality;
    float qMul() { return amzp_quality < 1.5 ? 0.25 : (amzp_quality < 2.5 ? 0.5 : (amzp_quality < 3.5 ? 1.0 : (amzp_quality < 4.5 ? 1.5 : 2.0))); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float hraw(float2 uv) {
        float4 c = layerAt(uv);
        float v = int(amzp_property) == 1 ? c.a : (c.a > 0.0001 ? dot(c.rgb / c.a, float3(0.299, 0.587, 0.114)) * c.a : 0.0);
        float lo = min(amzp_cutMin, amzp_cutMax - 0.001);
        return clamp((v - lo) / max(amzp_cutMax - lo, 0.001), 0.0, 1.0);
    }
    float hs(float2 uv, float2 px) {
        float r = max(amzp_softness, 0.0);
        if (r < 0.5) return hraw(uv);
        float acc = hraw(uv) * 2.0;
        float w = 2.0;
        float nd = max(4.0, floor(8.0 * qMul() + 0.5));
        for (int i = 0; i < 16; i++) {
            if (float(i) >= nd) break;
            float a = float(i) * 6.2831853 / nd;
            float2 d = float2(cos(a), sin(a)) * px;
            acc += hraw(uv + d * r) + hraw(uv + d * r * 0.5) * 1.5;
            w += 2.5;
        }
        return acc / w;
    }
    void amzRender() {
        float2 W = layer;
        float2 px = 1.0 / W;
        float2 uv = amzLayerNorm();
        float4 c = layerAt(uv);
        if (c.a <= 0.0001) { amzOutput = float4(0.0); return; }
        float e = max(1.0, amzp_softness * 0.35);
        float hx = hs(uv + float2(px.x * e, 0.0), px) - hs(uv - float2(px.x * e, 0.0), px);
        float hy = hs(uv + float2(0.0, px.y * e), px) - hs(uv - float2(0.0, px.y * e), px);
        float k = amzp_height * 12.0 / e;
        float3 n = normalize(float3(-hx * k, -hy * k, 1.0));
        float la = radians(amzp_lightDir), le = radians(amzp_lightHeight);
        float3 L = normalize(float3(cos(la) * cos(le), -sin(la) * cos(le), sin(le)));
        float3 V = float3(0.0, 0.0, 1.0);
        float3 H = normalize(L + V);
        float nl = max(dot(n, L), 0.0);
        float shin = mix(200.0, 4.0, clamp(amzp_roughness, 0.0, 1.0));
        float sp = pow(max(dot(n, H), 0.0), shin) * amzp_specular * (shin + 8.0) / 64.0;
        float3 base = c.rgb / c.a;
        float3 lc = amzp_lightColor.rgb * amzp_intensity;
        float3 specCol = mix(float3(1.0), base, clamp(amzp_metal, 0.0, 1.0));
        float3 col = base * (amzp_ambient + amzp_diffuse * nl * lc) * (1.0 - amzp_metal * 0.5) + specCol * sp * lc;
        col = clamp(col, 0.0, 1.0);
        amzOutput = float4(col * c.a, c.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
